import java.io.*;import java.util.*;public class Main{public static void main(String[] args) throws Exception{BufferedReader br=new BufferedReader(new InputStreamReader(System.in));StringBuilder out=new StringBuilder();int T=Integer.parseInt(br.readLine().trim());while(T-- >0){int N=Integer.parseInt(br.readLine().trim());int[] a=new int[N];StringTokenizer st=new StringTokenizer(br.readLine());for(int i=0;i<N;i++)a[i]=Integer.parseInt(st.nextToken());int K=Integer.parseInt(br.readLine().trim());int target=a[K-1];int pos=1;for(int i=0;i<N;i++)if(a[i]<target)pos++;out.append(pos).append('\n');}System.out.print(out.toString());}}